#!/usr/bin/env python3
"""The check for currency-coverage/c1. Generated by eval/build_tasks.py; run it
as `python3 check.py <workspace>`. Exit 0 is a pass."""

import json
import re
import shutil
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[3]))
from checklib import CAMEL, SNAKE, main  # noqa: E402


def check(ws):
    ws.check("./dev test passes", *ws.dev("test"))
    pattern = re.compile(r"\bdiscounted_unit_price\b")
    files = sorted(p for p in (ws.root / "tests").glob("test*.py") if pattern.search(p.read_text()))
    ws.check("a test module covers discounted_unit_price", bool(files), "no tests/test*.py mentions discounted_unit_price")
    ws.signals["followed"] = any(re.search(r"\b(JPY|BHD)\b", p.read_text()) for p in files)
    if files:
        modules = ["tests." + p.stem for p in files]
        for f in (ws.task / "check-data" / "mutant").rglob("*"):
            if f.is_file():
                shutil.copy2(f, ws.root / f.relative_to(ws.task / "check-data" / "mutant"))
        ok, out = ws.run([sys.executable, "-m", "unittest", *modules])
        ws.check("rule: the tests catch discounted_unit_price rounding as if every currency had two decimals", not ok,
                 "the tests still pass when discounted_unit_price rounds JPY to two decimals")

check.restore_tests = False


if __name__ == "__main__":
    main(check)
